-- Clipse Clipboard Floating Window Rule
hl.window_rule({
    name  = "clipse-floating-window",
    match = { title = "clipse-clipboard" },

    float = true,
    center = true,
    size = "640 540",
    pin = true,
    stay_focused = true,
})

-- Yazi Floating Terminal Window Rule
hl.window_rule({
    name  = "yazi-floating-window",
    match = { title = "yazi-filemanager" },

    float = true,
    center = true,
})

-- File Pickers & Dialogs Floating & Transparency Window Rules
hl.window_rule({
    name    = "dialog-pickers-floating",
    match   = { title = "^(Open.*|Save.*|Choose.*|Select.*|File Upload|All Files)$" },
    float   = true,
    center  = true,
    size    = "860 540",
    opacity = "0.88 0.80",
})

